function surfside_tools_mobile_api_events(WP_REST_Request $request){$start=$request->get_param('start');$end=$request->get_param('end');$limit=min(100,max(1,absint($request->get_param('limit')?:50)));if(!$start)$start=current_time('Y-m-d');if(!$end)$end=wp_date('Y-m-d',strtotime($start.' +1 year'));if($end<$start)return new WP_Error('surfside_invalid_date_range','The end date must be on or after the start date.',array('status'=>400));$start_date=new DateTimeImmutable($start);$end_date=new DateTimeImmutable($end);if($end_date>$start_date->modify('+2 years'))return new WP_Error('surfside_date_range_too_large','The requested date range cannot exceed two years.',array('status'=>400));$occurrences=surfside_tools_calendar_get_occurrences($start,$end,$limit);$events=array_map('surfside_tools_mobile_api_event',$occurrences);return rest_ensure_response(array('api_version'=>1,'generated_at'=>current_datetime()->format(DATE_ATOM),'range'=>array('start'=>$start,'end'=>$end),'count'=>count($events),'events'=>array_values($events)));}
