function surfside_tools_mobile_api_next_service($next){if(!$next||empty($next['date'])||empty($next['service']))return null;$service=(array)$next['service'];return array('key'=>(string)($service['key']??''),'label'=>(string)($service['label']??''),'starts_at'=>$next['date']->format(DATE_ATOM));}
function surfside_tools_mobile_api_timestamp($timestamp){$timestamp=absint($timestamp);return $timestamp?wp_date(DATE_ATOM,$timestamp):null;}
